mapper.select:
SELECT 
FROM sekai_Draw_lots_focus_session
WHERE user_id = #{userId}
ORDER BY completed_time DESC, id DESC
LIMIT #{limit}

SELECT COALESCE(SUM(actual_minutes), 0)
FROM sekai_Draw_lots_focus_session
WHERE user_id = #{userId}
  AND completed_time >= #{since}

SELECT COALESCE(SUM(actual_minutes), 0)
FROM sekai_Draw_lots_focus_session
WHERE user_id = #{userId}
  AND completed_time >= #{start}
  AND completed_time < #{end}

SELECT COUNT(*)
FROM sekai_Draw_lots_focus_session
WHERE user_id = #{userId}
  AND completed_time >= #{since}

SELECT COUNT(*)
FROM sekai_Draw_lots_focus_session
WHERE user_id = #{userId}

SELECT COUNT(*) FROM (
    SELECT DATE(completed_time) AS active_day
    FROM sekai_Draw_lots_focus_session
    WHERE user_id = #{userId}
      AND completed_time >= #{since}
    GROUP BY DATE(completed_time)
) active_days
